import {combatProfile,combatEligible,reserveLoss,returnReserve,openBattle,fireCannon,finishExpired,claimBattle,fireAtPirate,defeatNPC,PIRATE_ZONES,cargoCount,addCargo} from './combat-core.js?v=2026.11.09-frontiers';
import {cannonStats,currentHP} from './cannons.js?v=2026.11.09-frontiers';
import {usedSpace,capacity} from './engine.js?v=2026.11.09-frontiers';
import {mapDistance} from './world-wrap.js?v=2026.11.09-frontiers';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roll=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296;
export function createCombat(api){
 const a=api.account,get=api.getState;let slot=null,room=null,roomId=null,invites={},stops=[],positionStop=null,roomStop=null,positions={},sending=false,preparing=null,busy=false,lastProfile='',lastPos='',lastPosAt=0,lastProfileAt=0;
 const entry=document.createElement('button');entry.className='nav-item';entry.textContent='⚔ 전투·해적';entry.onclick=show;$('.main-nav').append(entry);
 const cue=document.createElement('button');cue.className='combat-alert';cue.hidden=true;cue.onclick=show;$('.chart').append(cue);
 const now=()=>Date.now()+(a.serverOffset||0),ref=path=>a.sdk.ref(a.db,'gameV2/'+path),read=async path=>(await a.sdk.get(ref(path))).val();
 function myPosition(){return {point:[...get().position],at:now()};}
 function peer(uid){return api.visible().find(p=>p.uid===uid);}
 function profileAt(uid,p){const boat=peer(uid);if(uid===a.uid)return {...p,...myPosition()};if(!boat)throw Error('상대 선장이 내 시야 안에 없어요.');return {...p,point:[boat.lon,boat.lat],at:boat.updatedAt};}
 async function commit(kind,key,fn){if(busy)throw Error('이전 처리를 확인 중이에요.');busy=true;try{const result=await a.atomicAction(kind,key,fn);api.changed();if(result?.message)api.toast(result.message);if(result?.broken){api.pause();setTimeout(()=>api.rescue(),0);}return result;}finally{busy=false;}}
 function notice(){cue.hidden=!slot&&!Object.keys(invites).length;cue.textContent=slot?(slot.startsWith('npc:')?'⚔ 해적 전투 계속하기':room?.status==='closed'?'⚑ 전투 결과·정산 받기':'⚔ 전투 중 · 대포 열기'):'⚔ 결투 요청 '+Object.keys(invites).length+'건';}
 async function connect(){if(!a.ready)return;dispose();slot=await read('combatSlots/'+a.uid);if(slot)watchRoom(slot);const s=a.sdk;stops.push(s.onValue(ref('combatSlots/'+a.uid),snap=>{const next=snap.val();if(next!==slot){slot=next;watchRoom(next);}notice();}));stops.push(s.onValue(s.query(ref('combatInvites/'+a.uid),s.orderByChild('at'),s.startAt(now()-60000),s.limitToLast(10)),snap=>{invites=snap.val()||{};notice();}));await publish(true);if(get().port&&!slot&&get().battleReserve)await releaseIfPort();stops.push(()=>clearInterval(timer));const timer=setInterval(()=>{publish();refreshTimes();},250);notice();}
 function watchRoom(id){roomStop?.();positionStop?.();roomStop=positionStop=null;room=null;roomId=id;positions={};if(!id||id.startsWith('npc:')){delete get().battleId;notice();return;}get().battleId=id;roomStop=a.sdk.onValue(ref('shared/battles/'+id),snap=>{room=snap.val()?.content||null;if(room?.status==='active'&&room.mode==='duel')api.pause();if(room?.status==='closed')positionStop?.();if($('#combat-board'))paintBattle();notice();});positionStop=a.sdk.onValue(ref('combatPositions/'+id),snap=>positions=snap.val()||{});}
 async function publish(force=false){if(!a.ready||!a.sdk||sending||a.lost)return;sending=true;try{const p=combatProfile(get(),a.name,now()),{point,at,...info}=p,signature=JSON.stringify(info);if(force||signature!==lastProfile||now()-lastProfileAt>=30000){if(force||signature!==lastProfile)await a.sdk.set(ref('combatProfiles/'+a.uid),{...info,at:a.sdk.serverTimestamp()});else await a.sdk.update(ref('combatProfiles/'+a.uid),{at:a.sdk.serverTimestamp()});lastProfile=signature;lastProfileAt=now();}
  if(room?.status==='active'){const pos=myPosition(),sig=JSON.stringify(pos.point.map(n=>+n.toFixed(5))),interval=room.mode==='duel'?250:2000;if((sig!==lastPos&&now()-lastPosAt>=interval)||now()-lastPosAt>=30000){await a.sdk.set(ref('combatPositions/'+roomId+'/'+a.uid),{point:pos.point,at:a.sdk.serverTimestamp()});lastPos=sig;lastPosAt=now();}}
 }catch{/* A failed profile publish protects this captain from new attacks. */}finally{sending=false;}}
 async function prepare(){if(preparing)return preparing;if(slot)throw Error('진행 중인 전투를 먼저 마치세요.');if(get().battleReserve)return true;preparing=commit('personal',a.uid,(game)=>{const reserve=reserveLoss(game,crypto.randomUUID());return {ok:true,extras:{['combatVaults/'+a.uid]:reserve}};}).then(async()=>{await publish(true);return true;}).finally(()=>preparing=null);return preparing;}
 async function releaseIfPort(){if(!get().port)return;if(slot){if(room?.status==='closed')await claim();else throw Error('전투 결과를 먼저 정산하세요.');}if(!get().battleReserve)return;await commit('personal',a.uid,game=>{if(!game.port)throw Error('입항 후 정산금을 반환하세요.');returnReserve(game);return {ok:true,extras:{['combatVaults/'+a.uid]:null}};});await publish(true);}
 async function invite(uid){if(!peer(uid))throw Error('시야 안의 선장에게 요청하세요.');await prepare();const existing=await read('combatInvites/'+uid+'/'+a.uid);if(existing&&now()-existing.at<10000)throw Error('요청 후 10초 뒤 다시 보낼 수 있어요.');await a.sdk.set(ref('combatInvites/'+uid+'/'+a.uid),{from:a.uid,name:a.name,at:a.sdk.serverTimestamp()});api.toast('결투 요청을 보냈어요. 60초 동안 수락할 수 있어요.');}
 async function begin(uid,mode){if(!peer(uid))throw Error('시야 안의 선장이에요. 가까운 바다에서 다시 확인하세요.');await prepare();await publish(true);const id=crypto.randomUUID(),[target,vaultA,vaultB,slotA,slotB]=await Promise.all([read('combatProfiles/'+uid),read('combatVaults/'+a.uid),read('combatVaults/'+uid),read('combatSlots/'+a.uid),read('combatSlots/'+uid)]);if(slotA||slotB)throw Error('이미 전투 중인 선장이 있어요.');const profiles={[a.uid]:combatProfile(get(),a.name,now()),[uid]:profileAt(uid,target||{})};combatEligible(profiles[a.uid],profiles[uid],now(),api.nav().clear.bind(api.nav()));await commit('battles',id,(game,c,time)=>{if(c.status)throw Error('이미 사용한 전투 번호예요.');if(game.port||game.voyage?.kind)throw Error('항구 밖 정상 항해 중에 시작하세요.');Object.assign(c,openBattle(mode,a.uid,uid,profiles,{[a.uid]:vaultA,[uid]:vaultB},time,api.nav().clear.bind(api.nav())));if(mode==='duel')c.inviteFrom=uid;game.battleId=id;return {ok:true,message:mode==='duel'?'결투를 수락했어요.':'해상 전투를 시작했어요.',extras:{['combatSlots/'+a.uid]:id,['combatSlots/'+uid]:id}};});slot=id;watchRoom(id);show();}
 async function shoot(id){await commit('battles',roomId,(_game,c,time)=>fireCannon(c,a.uid,id,time,roll(),{...positions,[a.uid]:myPosition()},api.nav().clear.bind(api.nav())));}
 async function end(surrender=false){await commit('battles',roomId,(_game,c,time)=>finishExpired(c,a.uid,time,{...positions,[a.uid]:myPosition()},surrender));}
 async function claim(){const id=roomId;const result=await commit('battles',id,(game,c,time)=>({...claimBattle(game,c,a.uid,time),extras:{['combatSlots/'+a.uid]:null,['combatVaults/'+a.uid]:null}}));slot=null;room=null;watchRoom(null);notice();await publish(true);return result;}
 function safe(fn){return async()=>{try{await fn();}catch(e){api.toast(e.message,'error');if($('#combat-message'))$('#combat-message').textContent=e.message;}};}
 function show(){if(slot&&!slot.startsWith('npc:'))return paintBattle();if(get().npcBattle)return showPirate(get().npcBattle.zoneId);const s=get(),peers=api.visible().filter(p=>p.uid!==a.uid);api.modal('해상 전투와 해적 토벌','대포는 항구의 대포·수리 메뉴에서 구입·장착',`<p>기본 사거리 180해리. 합의 결투는 피해 ×1.5, 명중 +10%p, 재장전 ×0.7. 항구·구조·패전 직후는 보호됩니다.</p><p>패배 시 돈 10%(최대 2,000 D), 화물 10%(최대 5상자)와 수리비를 잃고 방문한 항구로 구조돼요. 출항 전 손실 한도만 보관하며 남은 금액은 전투 뒤 또는 입항 때 반환해요.</p>${Object.entries(invites).filter(([,r])=>now()-r.at<60000).map(([uid,r])=>`<article><h3>${esc(r.name)}의 결투 요청</h3><button data-accept="${uid}">강화 결투 수락</button><button data-decline="${uid}">거절</button></article>`).join('')}<h3>시야 안 선장</h3>${peers.length?peers.map(p=>`<article><strong>${esc(p.name)}</strong><div class="dialog-actions"><button data-invite="${p.uid}">결투 요청</button><button data-free="${p.uid}">기본 대포로 공격</button></div></article>`).join(''):'<p>시야 안의 다른 배가 없어요.</p>'}<h3>해적 해역</h3><p>해적은 먼저 공격하지 않습니다. 선장이 먼저 쏜 뒤에만 반격해요.</p>${PIRATE_ZONES.map(z=>`<article><strong>${esc(z.name)}</strong><p>${Math.round(mapDistance(s.position,z.point))}해리 · 명성 ${[50,150,400][z.tier]} · ${now()<(s.pirateRespawns?.[z.id]||0)?'토벌 후 30분 대기':'출현'}</p><button data-pirate="${z.id}">해적선 확인</button><button data-pirate-look="${z.id}">해역 보기</button></article>`).join('')}<button id="combat-loot">항구에서 전리품 받기 · ${cargoCount(s.lootClaims)}/50상자</button><p id="combat-message" role="status"></p>`,'wide');document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=safe(()=>begin(b.dataset.accept,'duel')));document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=safe(async()=>{await a.sdk.remove(ref('combatInvites/'+a.uid+'/'+b.dataset.decline));show();}));document.querySelectorAll('[data-invite]').forEach(b=>b.onclick=safe(()=>invite(b.dataset.invite)));document.querySelectorAll('[data-free]').forEach(b=>b.onclick=()=>confirmAttack(b.dataset.free));document.querySelectorAll('[data-pirate]').forEach(b=>b.onclick=()=>showPirate(b.dataset.pirate));document.querySelectorAll('[data-pirate-look]').forEach(b=>b.onclick=()=>api.look(PIRATE_ZONES.find(z=>z.id===b.dataset.pirateLook).point));$('#combat-loot').onclick=safe(async()=>{await releaseIfPort();await commit('personal',a.uid,game=>{if(!game.port)throw Error('항구에서 수령하세요.');if(usedSpace(game)+cargoCount(game.lootClaims)>capacity(game))throw Error('전리품을 실을 화물 공간을 비우세요.');addCargo(game.cargo,game.lootClaims);game.lootClaims={};return {ok:true,message:'전리품을 화물칸에 실었어요.'};});show();});}
 function confirmAttack(uid){api.modal('이 선장을 공격할까요?','시야 안 자유 공격',`<p>상대의 동의 없이 기본 대포 성능으로 해상 전투를 시작합니다. 상대도 반격할 수 있어요.</p><button id="free-confirm">공격 시작</button><p id="combat-message"></p>`,'small');$('#free-confirm').onclick=safe(()=>begin(uid,'free'));}
 function paintBattle(){if(!room)return api.toast('전투 정보를 불러오는 중이에요.');const me=room.players[a.uid],enemy=room.players[room.a===a.uid?room.b:room.a];api.modal(room.mode==='duel'?'선장 간 강화 결투':'해상 포격전',room.status==='closed'?'전투 종료 · 서버 정산 대기':'대포마다 재장전 시간이 달라요',`<div id="combat-board"><div class="combat-hp"><p>${esc(me.name)} · 내구도 ${me.hp}/${me.maxHP}</p><meter min="0" max="${me.maxHP}" value="${me.hp}"></meter><p>${esc(enemy.name)} · 내구도 ${enemy.hp}/${enemy.maxHP}</p><meter min="0" max="${enemy.maxHP}" value="${enemy.hp}"></meter></div><p>${esc(room.event?.text)}</p>${room.status==='closed'?`<h3>${room.winner===a.uid?'승리':'패배'} · ${esc(room.reason)}</h3><button id="battle-claim" class="primary-button">결과 정산·계속하기</button>`:`<div class="dialog-actions">${(me.guns||[]).map(g=>`<button data-fire="${g.id}" data-ready="${g.readyAt||0}">${esc(cannonStats(g,room.mode==='duel').name)}</button>`).join('')||'<p>장착한 대포가 없어요. 항복하거나 제한 시간 판정을 기다리세요.</p>'}</div><p id="battle-countdown"></p><button id="battle-resolve">시간 종료·접속 종료 판정</button><button id="battle-surrender">항복하기</button>`}<p id="combat-message" role="status"></p></div>`,'medium');document.querySelectorAll('[data-fire]').forEach(b=>b.onclick=safe(()=>shoot(b.dataset.fire)));$('#battle-claim')?.addEventListener('click',safe(async()=>{await claim();api.close();}));$('#battle-resolve')?.addEventListener('click',safe(()=>end()));$('#battle-surrender')?.addEventListener('click',()=>{api.modal('항복할까요?','패전 손실과 구조 적용','<p>정해진 손실과 수리비를 정산한 뒤 방문했던 항구로 구조합니다.</p><button id="surrender-confirm">항복 확정</button>','small');$('#surrender-confirm').onclick=safe(async()=>{await end(true);paintBattle();});});refreshTimes();}
 function refreshTimes(){for(const b of document.querySelectorAll('[data-fire],[data-npc-fire]')){const g=b.dataset.fire?room?.players?.[a.uid]?.guns?.find(g=>g.id===b.dataset.fire):get().cannons?.find(g=>g.id===b.dataset.npcFire);if(!g)continue;const left=Math.max(0,(g.readyAt-now())/1000);b.disabled=left>0||busy;b.textContent=cannonStats(g,room?.mode==='duel').name+(left?' · '+left.toFixed(1)+'초':' · 발사');}if($('#battle-countdown'))$('#battle-countdown').textContent='제한 시간 '+Math.max(0,Math.ceil((room.deadline-now())/1000))+'초 · 범위 밖에서는 포격할 수 없어요.';}
 function showPirate(zoneId){const s=get(),z=PIRATE_ZONES.find(z=>z.id===zoneId),distance=mapDistance(s.position,z.point);api.modal(z.name,'개인별 해적 · 선제공격 없음',`<p>거리 ${Math.round(distance)}해리 · 사거리 180해리</p><p>내 내구도 ${currentHP(s)} · 해적 내구도 ${s.npcBattle?.zoneId===z.id?s.npcBattle.hp:[100,240,500][z.tier]}</p><p>토벌 명성 ${[50,150,400][z.tier]} · 재출현 30분. 반격 준비가 끝나면 다음 포격 교환에 반격합니다.</p><div class="dialog-actions">${(s.cannons||[]).filter(g=>g.shipId).map(g=>`<button data-npc-fire="${g.id}">${esc(cannonStats(g).name)}</button>`).join('')||'<p>항구에서 대포를 장착하세요.</p>'}</div>${s.npcBattle?'<button id="npc-surrender">후퇴·패전 구조</button>':''}<p id="combat-message"></p>`,'medium');document.querySelectorAll('[data-npc-fire]').forEach(b=>b.onclick=safe(async()=>{if(slot&&!slot.startsWith('npc:'))throw Error('선장 간 전투를 먼저 마치세요.');await commit('personal',a.uid,(game,_c,time)=>{const result=fireAtPirate(game,z.id,b.dataset.npcFire,time,[roll(),roll()],api.nav().clear.bind(api.nav()));result.extras={['combatSlots/'+a.uid]:game.npcBattle?'npc:'+a.uid:null,...(!game.battleReserve?{['combatVaults/'+a.uid]:null}:{})};return result;});showPirate(z.id);}));$('#npc-surrender')?.addEventListener('click',safe(async()=>{await commit('personal',a.uid,(game,_c,time)=>({...defeatNPC(game,time),extras:{['combatSlots/'+a.uid]:null,['combatVaults/'+a.uid]:null}}));api.close();}));refreshTimes();}
 async function prepareNPC(){if(slot?.startsWith('npc:'))return;if(slot)throw Error('다른 전투 중이에요.');await commit('personal',a.uid,()=>({ok:true,extras:{['combatSlots/'+a.uid]:'npc:'+a.uid}}));slot='npc:'+a.uid;}
 function dispose(){stops.forEach(fn=>fn());stops=[];roomStop?.();positionStop?.();}
 async function onArrival(){try{if(room?.status==='active'){api.toast('항구로 이탈해 전투를 마칩니다.');await end(true);await claim();}else await releaseIfPort();}catch(e){api.toast(e.message,'error');}}
 return {connect,dispose,show,showPirate,prepare,releaseIfPort,publish,onArrival,active:()=>room?.status==='active',retreatForRescue:async()=>{await end(true);await claim();},hasReserve:()=>!!get().battleReserve,blocked:()=>!!slot&&(slot.startsWith('npc:')||room?.status!=='active'||room?.mode==='duel')};
}
